 {
  use bevy::render::render_resource::*;use bevy::render::{renderer::RenderQueue,view::{ViewUniforms,ViewUniformOffset,ExtractedView}};
  let (device,queue,uniform,rows)={let rw=app.get_sub_app_mut(RenderApp).unwrap().world_mut();let device=rw.resource::<RenderDevice>().clone();let queue=rw.resource::<RenderQueue>().clone();let uniform=rw.resource::<ViewUniforms>().uniforms.buffer().ok_or("Caster view uniforms absent")?.clone();
   let mut query=rw.query::<(&bevy::pbr::ShadowView,&ExtractedView,&ViewUniformOffset)>();let rows=query.iter(rw).filter(|(_,v,_)|v.retained_view_entity.main_entity==light.into()&&v.retained_view_entity.auxiliary_entity==camera.into()&&v.clip_from_view.w_axis.w==1.).map(|(_,v,offset)|{let world=v.world_from_view.to_matrix();let clip=v.clip_from_world.unwrap_or(v.clip_from_view*world.inverse());(v.retained_view_entity.subview_index,offset.offset,clip.to_cols_array(),world.to_cols_array(),v.clip_from_view.to_cols_array())}).collect::<Vec<_>>();assert_eq!(rows.len(),4);(device,queue,uniform,rows)};
  let shader=device.create_and_validate_shader_module(ShaderModuleDescriptor{label:Some("source-caster-view-probe"),source:ShaderSource::Wgsl(std::fs::read_to_string(folder.join("caster-view-probe.wgsl"))?.into())});let pipeline=device.create_compute_pipeline(&RawComputePipelineDescriptor{label:Some("source-caster-view-probe"),layout:None,module:&shader,entry_point:Some("main"),compilation_options:default(),cache:None});
  let mut observations=Vec::new();
  for (cascade,offset,expected_clip,expected_world,expected_projection) in rows{
   let output=device.create_buffer(&BufferDescriptor{label:Some("source-caster-view-values"),size:448,usage:BufferUsages::STORAGE|BufferUsages::COPY_SRC,mapped_at_creation:false});let staging=device.create_buffer(&BufferDescriptor{label:Some("source-caster-view-readback"),size:448,usage:BufferUsages::COPY_DST|BufferUsages::MAP_READ,mapped_at_creation:false});let layout=pipeline.get_bind_group_layout(0);
   let bindings=device.wgpu_device().create_bind_group(&BindGroupDescriptor{label:Some("source-caster-view-bindings"),layout:&layout,entries:&[BindGroupEntry{binding:0,resource:BindingResource::Buffer(BufferBinding{buffer:&uniform,offset:offset as u64,size:std::num::NonZeroU64::new(448)})},BindGroupEntry{binding:1,resource:output.as_entire_binding()}]});
   let mut encoder=device.create_command_encoder(&CommandEncoderDescriptor{label:Some("source-caster-view-copy")});{let mut pass=encoder.begin_compute_pass(&ComputePassDescriptor{label:Some("source-caster-view-copy"),timestamp_writes:None});pass.set_pipeline(&pipeline);pass.set_bind_group(0,&bindings,&[]);pass.dispatch_workgroups(1,1,1);}encoder.copy_buffer_to_buffer(&output,0,&staging,0,448);queue.submit([encoder.finish()]);
   let slice=staging.slice(..);let (sender,receiver)=std::sync::mpsc::channel();slice.map_async(MapMode::Read,move|result|{let _=sender.send(result.is_ok());});let deadline=Instant::now()+Duration::from_secs(30);loop{device.poll(PollType::Poll)?;match receiver.try_recv(){Ok(mapped)=>{assert!(mapped);break;},Err(std::sync::mpsc::TryRecvError::Empty)=>{},Err(e)=>return Err(e.into())};if Instant::now()>deadline{return Err("Caster view uniform readback timeout".into());}std::thread::sleep(Duration::from_millis(5));}
   let data=slice.get_mapped_range();let values=data.chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect::<Vec<_>>();assert_eq!(values.len(),112);assert!(values.iter().all(|v|v.is_finite()));std::fs::write(folder.join(format!("CASTER-VIEW-{view}-{cascade}.float32")),&data)?;drop(data);staging.unmap();
   let gpu_clip=&values[0..16];let gpu_world=&values[48..64];let gpu_projection=&values[80..96];let checks=[(gpu_clip,expected_clip),(gpu_world,expected_world),(gpu_projection,expected_projection)];let mismatches=checks.iter().map(|(gpu,cpu)|gpu.iter().zip(cpu).filter(|(a,b)|a.to_bits()!=b.to_bits()).count()).sum::<usize>();
   observations.push(serde_json::json!({"cascade":cascade,"uniform_offset":offset,"gpu_values":values,"cpu_clip_from_world":expected_clip,"cpu_world_from_view":expected_world,"cpu_clip_from_view":expected_projection,"gpu_cpu_matrix_bit_mismatches":mismatches,"cpu_gpu_scalars_compared":48}));
  }
  observations.sort_by_key(|row|row["cascade"].as_u64().unwrap());std::fs::write(folder.join(format!("CASTER-VIEW-GPU-{view}.json")),serde_json::to_vec_pretty(&serde_json::json!({"view":view,"source_uniform_buffer_bound":true,"orthographic_cascades":observations,"gpu_scalars_read":448,"cpu_gpu_scalars_compared":192,"full_import":false}))?)?;
  assert!(observations.iter().all(|row|row["gpu_cpu_matrix_bit_mismatches"].as_u64()==Some(0)),"Caster view GPU matrices differ from extracted views");
 }
